        int right = originalWidth > originalHeight ? 0 : originalHeight - originalWidth;
        int bottom = originalHeight > originalWidth ? 0 : originalWidth - originalHeight;
        // Padding to make the image square
        cv::cuda::copyMakeBorder(img, img, 0, bottom, 0, right, cv::BORDER_CONSTANT, cv::Scalar(0, 0, 0));
