                                  static_cast<int64_t>(src_imgs[0].cols)};

    long long step = batch_image.step / sizeof(float);

    std::vector<int64_t> strides = {1, 1, step, static_cast<int64_t>(batch_image.channels())};

    torch::Tensor input_tensor = torch::from_blob(batch_image.data, sizes, strides, torch::kCUDA).contiguous().to(device_type);
    return input_tensor;
